const falseValues = new Set(['no', 'false', '0', 'skip', 'n']);

function normalizeKey(key) {
  return String(key || '')
    .trim()
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '_')
    .replace(/^_+|_+$/g, '');
}

function pick(row, keys) {
  const normalized = Object.fromEntries(Object.entries(row).map(([key, value]) => [normalizeKey(key), value]));
  for (const key of keys) {
    const value = normalized[normalizeKey(key)];
    if (value !== undefined && value !== null && String(value).trim() !== '') return String(value).trim();
  }
  return '';
}

function channelEnabled(value, fallback) {
  if (value === undefined || value === null || String(value).trim() === '') return fallback;
  return !falseValues.has(String(value).trim().toLowerCase());
}

function escapeHtml(value) {
  return String(value || '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');
}

function cleanPhone(value) {
  return String(value || '').replace(/[^\d]/g, '');
}

const output = [];

for (const item of $input.all()) {
  const row = item.json;
  const name = pick(row, ['name', 'client_name', 'full_name', 'contact_name']);
  const firstName = name.split(/\s+/).filter(Boolean)[0] || 'there';
  const phoneRaw = pick(row, ['phone', 'mobile', 'number', 'contact_number', 'whatsapp', 'whatsapp_number']);
  const phone = cleanPhone(phoneRaw);
  const email = pick(row, ['email', 'email_address', 'gmail']);
  const propertyType = pick(row, ['property_type', 'property', 'interest', 'requirement']) || 'property';
  const location = pick(row, ['location', 'area', 'city', 'preferred_location']);
  const budget = pick(row, ['budget', 'price_range', 'range']);
  const notes = pick(row, ['notes', 'remarks', 'comments']);

  const defaultWhatsApp = [
    `Hi ${firstName}, this is a quick follow-up regarding your ${propertyType} requirement${location ? ` in ${location}` : ''}.`,
    budget ? `I noted your budget as ${budget}.` : '',
    'Please let me know a good time to share suitable options.'
  ].filter(Boolean).join(' ');

  const defaultSubject = `Property options${location ? ` in ${location}` : ''}`;
  const defaultEmail = [
    `<p>Hi ${escapeHtml(firstName)},</p>`,
    `<p>I am following up regarding your ${escapeHtml(propertyType)} requirement${location ? ` in ${escapeHtml(location)}` : ''}${budget ? ` with budget ${escapeHtml(budget)}` : ''}.</p>`,
    notes ? `<p>Notes: ${escapeHtml(notes)}</p>` : '',
    '<p>Please reply with a convenient time and I will share suitable options.</p>',
    '<p>Regards,<br>Property Team</p>'
  ].filter(Boolean).join('\n');

  const whatsappMessage = pick(row, ['whatsapp_message', 'whatsapp_text', 'message']) || defaultWhatsApp;
  const emailSubject = pick(row, ['email_subject', 'subject']) || defaultSubject;
  const emailHtml = pick(row, ['email_body', 'email_html', 'body']) || defaultEmail;
  const sendWhatsapp = channelEnabled(pick(row, ['send_whatsapp', 'whatsapp_enabled']), Boolean(phone));
  const sendEmail = channelEnabled(pick(row, ['send_email', 'email_enabled']), Boolean(email));

  if (!sendWhatsapp && !sendEmail) continue;

  output.push({
    json: {
      name,
      firstName,
      phoneRaw,
      phone,
      email,
      propertyType,
      location,
      budget,
      notes,
      whatsappMessage,
      emailSubject,
      emailHtml,
      sendWhatsapp: sendWhatsapp && Boolean(phone),
      sendEmail: sendEmail && Boolean(email),
      sourceRow: row
    }
  });
}

return output;
